<?php

namespace LibreNMS\Tests\Unit\Models;

use App\Models\AlertFault;
use App\Models\AlertLog;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Facades\Validator;
use LibreNMS\Tests\TestCase;
use PHPUnit\Framework\Attributes\DataProvider;

/**
 * Checks the SQL generated by the faults and alert history filters, no database needed.
 */
final class AlertFiltersTest extends TestCase
{
    /**
     * @return array<string, array{class-string<AlertFault|AlertLog>}>
     */
    public static function models(): array
    {
        return [
            'faults' => [AlertFault::class],
            'alert log' => [AlertLog::class],
        ];
    }

    /**
     * @param  class-string<AlertFault|AlertLog>  $model
     */
    #[DataProvider('models')]
    public function testEveryFilterFieldIsApplied(string $model): void
    {
        $base = $model::query()->toSql();

        foreach ($model::filterFieldDefinitions() as $field) {
            $sql = $model::query()->applyFilters([$field['key'] => ['eq' => '1']])->toSql();
            $this->assertNotEquals($base, $sql, "Filter field {$field['key']} is shown but not filterable");
        }
    }

    /**
     * @param  class-string<AlertFault|AlertLog>  $model
     */
    #[DataProvider('models')]
    public function testUnlistedFieldsAreIgnored(string $model): void
    {
        $base = $model::query()->toSql();

        foreach (['open', 'alert_faults.open', 'details', 'device.community', 'device.authpass', 'rule.builder', 'state`=1 or 1=1 -- '] as $field) {
            $this->assertEquals($base, $model::query()->applyFilters([$field => ['eq' => '0']])->toSql(), "$field should not be filterable");
        }
    }

    public function testStateIsQualified(): void
    {
        // alert_log is joined to a grouped subquery that also has a state column
        $this->assertSql('`alert_log`.`state` in (?, ?)', ['0', '1'], AlertLog::query()->applyFilters(['state' => ['in' => '0,1']]));
        $this->assertSql('not `alert_faults`.`state` = ?', ['2'], AlertFault::query()->applyFilters(['state' => ['neq' => '2']]));
    }

    /**
     * @param  class-string<AlertFault|AlertLog>  $model
     */
    #[DataProvider('models')]
    public function testSearchMatchesRuleAndDevice(string $model): void
    {
        $query = $model::query()->applyFilters(['search' => ['contains' => 'core']]);

        $this->assertSql('exists (select * from `alert_rules` where', [], $query);
        $this->assertSql('`name` like ?', [], $query);
        $this->assertSql('or exists (select * from `devices` where', [], $query);
        $this->assertSql('`hostname` like ?', [], $query);
        $this->assertSame(['%core%', '%core%', '%core%', '%core%'], $query->getBindings());
    }

    /**
     * @param  class-string<AlertFault|AlertLog>  $model
     */
    #[DataProvider('models')]
    public function testRelationFilters(string $model): void
    {
        $this->assertSql('`alert_rules`.`id` and `severity` in (?, ?))', ['warning', 'critical'], $model::query()->applyFilters(['rule.severity' => ['in' => 'warning,critical']]));
        $this->assertSql('`location_id` = ?', ['5'], $model::query()->applyFilters(['device.location_id' => ['eq' => '5']]));
        $this->assertSql('not exists (select * from `devices`', [], $model::query()->applyFilters(['device.groups.id' => ['is_empty' => null]]));
    }

    public function testUnreachable(): void
    {
        $unreachable = AlertFault::query()->applyFilters(['unreachable' => ['eq' => '1']])->toSql();
        $this->assertStringContainsString('exists (select * from `device_relationships`', $unreachable);
        $this->assertStringContainsString('and not exists (select * from `device_relationships` inner join `devices` as `parent_devices`', $unreachable);

        $reachable = AlertFault::query()->applyFilters(['unreachable' => ['eq' => '0']])->toSql();
        $this->assertStringContainsString('(not exists (select * from `device_relationships`', $reachable);
        $this->assertStringContainsString('or exists (select * from `device_relationships` inner join', $reachable);
    }

    /**
     * @return array<string, array{mixed, bool}>
     */
    public static function filterValues(): array
    {
        return [
            'string' => [['state' => ['eq' => '1']], true],
            'int' => [['state' => ['eq' => 1]], true],
            'null' => [['state' => ['is_empty' => null]], true],
            'comma list' => [['state' => ['in' => '1,2']], true],
            'flat list for set operator' => [['state' => ['in' => ['1', '2']]], true],
            'list for scalar operator' => [['state' => ['eq' => ['1', '2']]], false],
            'list for pattern operator' => [['search' => ['contains' => ['a']]], false],
            'nested list' => [['state' => ['in' => [['1']]]], false],
            'unknown operator' => [['state' => ['bogus' => '1']], false],
            'too long' => [['search' => ['contains' => str_repeat('a', 256)]], false],
        ];
    }

    #[DataProvider('filterValues')]
    public function testFilterValidation(mixed $filter, bool $valid): void
    {
        $validator = Validator::make(['filter' => $filter], AlertFault::filterValidationRules());

        $this->assertSame($valid, $validator->passes(), json_encode($validator->errors()->all()));
    }

    /**
     * @param  list<string>  $bindings
     * @param  Builder<covariant \Illuminate\Database\Eloquent\Model>  $query
     */
    private function assertSql(string $expected, array $bindings, Builder $query): void
    {
        $this->assertStringContainsString($expected, $query->toSql());
        foreach ($bindings as $binding) {
            $this->assertContains($binding, $query->getBindings());
        }
    }
}
